package store

import (
	"errors"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Coupon errors. Callers check them with errors.Is.
var (
	ErrCodeTaken            = errors.New("a coupon with this code already exists")
	ErrSubscriptionCanceled = errors.New("the subscription is canceled")
	ErrCouponApplied        = errors.New("the subscription already has a coupon")
	ErrCouponExpired        = errors.New("the coupon can no longer be redeemed")
	ErrCouponExhausted      = errors.New("the coupon has no redemptions left")
	ErrCurrencyMismatch     = errors.New("the coupon is in another currency than the plan")
)

var couponCodeRe = regexp.MustCompile(`^[A-Za-z0-9_-]{3,32}$`)

// CreateCoupon adds a coupon. Its code is unique in the organization, ignoring case.
func (s *Store) CreateCoupon(c Coupon, now time.Time) (Coupon, error) {
	if err := checkCoupon(c); err != nil {
		return Coupon{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[c.OrgID]; !ok {
		return Coupon{}, ErrNotFound
	}
	if _, ok := s.couponByCode(c.OrgID, c.Code); ok {
		return Coupon{}, ErrCodeTaken
	}
	c.ID = s.newID("cpn")
	c.CreatedAt = now.UTC()
	if c.RedeemBy != nil {
		t := c.RedeemBy.UTC()
		c.RedeemBy = &t
	}
	s.coupons[c.ID] = c
	return c, nil
}

func checkCoupon(c Coupon) error {
	if !couponCodeRe.MatchString(c.Code) {
		return invalid("a coupon code is 3 to 32 letters, digits, dashes or underscores")
	}
	hasPct, hasAmt := c.PercentOff != 0, c.AmountOff != 0
	switch {
	case hasPct == hasAmt:
		return invalid("a coupon takes a percentage off or an amount off, not both or neither")
	case hasPct && (c.PercentOff < 1 || c.PercentOff > 100):
		return invalid("a percentage off is 1 to 100")
	case hasPct && c.Currency != "":
		return invalid("a percentage off has no currency")
	case hasAmt && c.AmountOff < 0:
		return invalid("an amount off is positive")
	case hasAmt && !c.Currency.Valid():
		return invalid("unknown currency %q", c.Currency)
	}
	switch c.Duration {
	case CouponOnce, CouponForever:
		if c.DurationInMonths != 0 {
			return invalid("only a repeating coupon has a duration in months")
		}
	case CouponRepeating:
		if c.DurationInMonths < 1 || c.DurationInMonths > 36 {
			return invalid("a repeating coupon lasts 1 to 36 months")
		}
	default:
		return invalid("a coupon lasts once, repeating or forever")
	}
	if c.MaxRedemptions < 0 {
		return invalid("a coupon's maximum redemptions is at least 1")
	}
	return nil
}

// Coupon returns one of an organization's coupons by its code, ignoring case.
func (s *Store) Coupon(orgID, code string) (Coupon, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.couponByCode(orgID, code)
}

// couponByCode is Coupon for a caller that holds the lock.
func (s *Store) couponByCode(orgID, code string) (Coupon, bool) {
	for _, c := range s.coupons {
		if c.OrgID == orgID && strings.EqualFold(c.Code, code) {
			return c, true
		}
	}
	return Coupon{}, false
}

// Coupons returns an organization's coupons, oldest first.
func (s *Store) Coupons(orgID string) []Coupon {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Coupon{}
	for _, c := range s.coupons {
		if c.OrgID == orgID {
			out = append(out, c)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// CouponRedemptions counts the organization's subscriptions that have the coupon with this code applied.
func (s *Store) CouponRedemptions(orgID, code string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.redemptions(orgID, code)
}

// redemptions is CouponRedemptions for a caller that holds the lock. The code must be the coupon's own.
func (s *Store) redemptions(orgID, code string) int {
	n := 0
	for _, sub := range s.subs {
		if sub.OrgID == orgID && sub.Coupon == code {
			n++
		}
	}
	return n
}

// ApplyCoupon applies a coupon to a subscription. now is the redemption time. A subscription has at most one coupon, and a
// coupon may be refused: see the errors above.
func (s *Store) ApplyCoupon(orgID, subID, code string, now time.Time) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	c, ok := s.couponByCode(orgID, code)
	if !ok {
		return Subscription{}, ErrNotFound
	}
	switch {
	case sub.Status == Canceled:
		return Subscription{}, ErrSubscriptionCanceled
	case sub.Coupon != "":
		return Subscription{}, ErrCouponApplied
	case c.RedeemBy != nil && now.After(*c.RedeemBy):
		return Subscription{}, ErrCouponExpired
	case c.MaxRedemptions > 0 && s.redemptions(orgID, c.Code) >= c.MaxRedemptions:
		return Subscription{}, ErrCouponExhausted
	case c.AmountOff > 0 && s.plans[sub.PlanID].Currency != c.Currency:
		return Subscription{}, ErrCurrencyMismatch
	}
	t := now.UTC()
	sub.Coupon, sub.CouponRedeemedAt = c.Code, &t
	s.subs[subID] = sub
	return copySub(sub), nil
}

