// discount sets an invoice's discount for a subscription's coupon, when the coupon applies to an invoice created at now for a
// period starting at start. The coupon then replaces the subscription's own discount. Otherwise the invoice keeps that.
//   - once: only the first invoice created after the redemption.
//   - repeating: the invoices whose period starts less than its duration after the redemption.
//   - forever: every invoice created after the redemption.
func (s *Service) discount(inv *store.Invoice, sub store.Subscription, start, now time.Time) error {
	if sub.Coupon == "" || sub.CouponRedeemedAt == nil || now.Before(*sub.CouponRedeemedAt) {
		return nil
	}
	c, ok := s.Store.Coupon(sub.OrgID, sub.Coupon)
	if !ok {
		return store.ErrNotFound
	}
	var applies bool
	switch c.Duration {
	case store.CouponOnce:
		applies = !s.hasCouponInvoice(sub)
	case store.CouponRepeating:
		applies = start.Before(sub.CouponRedeemedAt.AddDate(0, c.DurationInMonths, 0))
	case store.CouponForever:
		applies = true
	}
	if !applies {
		return nil
	}
	inv.Coupon, inv.DiscountPercent, inv.DiscountAmount = c.Code, 0, 0
	if c.PercentOff > 0 {
		inv.DiscountPercent = c.PercentOff
	} else {
		inv.DiscountAmount = c.AmountOff
	}
	return nil
}

// hasCouponInvoice reports whether a coupon has already discounted one of a subscription's invoices.
func (s *Service) hasCouponInvoice(sub store.Subscription) bool {
	for _, inv := range s.Store.ListInvoices(sub.OrgID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
		if inv.Coupon != "" {
			return true
		}
	}
	return false
}

