package store

import (
	"errors"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

func TestCreateCouponValidation(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	bad := map[string]Coupon{
		"short code":            {Code: "AB", PercentOff: 10, Duration: CouponOnce},
		"long code":             {Code: strings.Repeat("A", 33), PercentOff: 10, Duration: CouponOnce},
		"space in code":         {Code: "SPRING 1", PercentOff: 10, Duration: CouponOnce},
		"both kinds of off":     {Code: "SPRING", PercentOff: 10, AmountOff: 100, Currency: money.USD, Duration: CouponOnce},
		"neither kind of off":   {Code: "SPRING", Duration: CouponOnce},
		"percent over 100":      {Code: "SPRING", PercentOff: 101, Duration: CouponOnce},
		"percent with currency": {Code: "SPRING", PercentOff: 10, Currency: money.USD, Duration: CouponOnce},
		"amount without money":  {Code: "SPRING", AmountOff: 100, Duration: CouponOnce},
		"amount in unknown currency": {Code: "SPRING", AmountOff: 100, Currency: "XYZ", Duration: CouponOnce},
		"unknown duration":      {Code: "SPRING", PercentOff: 10, Duration: "weekly"},
		"repeating without months": {Code: "SPRING", PercentOff: 10, Duration: CouponRepeating},
		"repeating 37 months":   {Code: "SPRING", PercentOff: 10, Duration: CouponRepeating, DurationInMonths: 37},
		"months on a once coupon": {Code: "SPRING", PercentOff: 10, Duration: CouponOnce, DurationInMonths: 3},
		"negative redemptions":  {Code: "SPRING", PercentOff: 10, Duration: CouponForever, MaxRedemptions: -1},
	}
	for name, c := range bad {
		c.OrgID = a.ID
		if _, err := s.CreateCoupon(c, t0); !errors.Is(err, ErrInvalid) {
			t.Errorf("%s: %v, want ErrInvalid", name, err)
		}
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: "org_missing", Code: "SPRING", PercentOff: 10, Duration: CouponOnce}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown organization: %v", err)
	}

	c, err := s.CreateCoupon(Coupon{OrgID: a.ID, Code: "Spring_24-A", PercentOff: 10, Duration: CouponOnce}, t0)
	if err != nil || c.ID == "" || !c.CreatedAt.Equal(t0) {
		t.Fatalf("CreateCoupon = %+v, %v", c, err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: a.ID, Code: "SPRING_24-a", PercentOff: 5, Duration: CouponOnce}, t0); !errors.Is(err, ErrCodeTaken) {
		t.Fatalf("code taken ignoring case: %v", err)
	}
	b := newOrg(t, s, "B")
	if _, err := s.CreateCoupon(Coupon{OrgID: b.ID, Code: "Spring_24-A", PercentOff: 5, Duration: CouponOnce}, t0); err != nil {
		t.Fatalf("the same code in another organization: %v", err)
	}
}

func TestCouponLookupAndList(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	first, _ := s.CreateCoupon(Coupon{OrgID: a.ID, Code: "FIRST", PercentOff: 10, Duration: CouponOnce}, t0)
	second, _ := s.CreateCoupon(Coupon{OrgID: a.ID, Code: "SECOND", AmountOff: 500, Currency: money.EUR, Duration: CouponForever}, t0)
	if got, ok := s.Coupon(a.ID, "second"); !ok || got.ID != second.ID {
		t.Fatalf("Coupon ignoring case = %+v, %v", got, ok)
	}
	if _, ok := s.Coupon("org_other", "FIRST"); ok {
		t.Fatal("a coupon of another organization was found")
	}
	if got := s.Coupons(a.ID); len(got) != 2 || got[0].ID != first.ID || got[1].ID != second.ID {
		t.Fatalf("Coupons = %+v, want oldest first", got)
	}
	st, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got, ok := st.Coupon(a.ID, "FIRST"); !ok || got.PercentOff != 10 {
		t.Fatalf("after Export and FromState: %+v, %v", got, ok)
	}
}

func TestApplyCoupon(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	usd, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	eur, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.EUR, UnitAmount: 2000, Interval: Monthly}, t0)
	newSub := func(plan Plan) Subscription {
		t.Helper()
		sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: plan.ID, Quantity: 1, Status: Active,
			StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
		if err != nil {
			t.Fatal(err)
		}
		return sub
	}
	create := func(c Coupon) {
		t.Helper()
		c.OrgID = a.ID
		if _, err := s.CreateCoupon(c, t0); err != nil {
			t.Fatal(err)
		}
	}
	create(Coupon{Code: "HALF", PercentOff: 50, Duration: CouponForever})
	create(Coupon{Code: "TENOFF", AmountOff: 1000, Currency: money.USD, Duration: CouponOnce})
	create(Coupon{Code: "EXPIRED", PercentOff: 5, Duration: CouponOnce, RedeemBy: &t0})
	create(Coupon{Code: "ONCE", PercentOff: 5, Duration: CouponOnce, MaxRedemptions: 1})

	sub := newSub(usd)
	if _, err := s.ApplyCoupon(a.ID, sub.ID, "NOPE", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown code: %v", err)
	}
	if _, err := s.ApplyCoupon(b.ID, sub.ID, "HALF", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription of another organization: %v", err)
	}
	if _, err := s.ApplyCoupon(a.ID, newSub(eur).ID, "TENOFF", t0); !errors.Is(err, ErrCurrencyMismatch) {
		t.Fatalf("amount in another currency: %v", err)
	}
	if _, err := s.ApplyCoupon(a.ID, sub.ID, "EXPIRED", t0.Add(time.Second)); !errors.Is(err, ErrCouponExpired) {
		t.Fatalf("after redeem_by: %v", err)
	}

	applied, err := s.ApplyCoupon(a.ID, sub.ID, "tenoff", t0.Add(time.Hour))
	if err != nil || applied.Coupon != "TENOFF" || applied.CouponRedeemedAt == nil || !applied.CouponRedeemedAt.Equal(t0.Add(time.Hour)) {
		t.Fatalf("ApplyCoupon = %+v, %v", applied, err)
	}
	if _, err := s.ApplyCoupon(a.ID, sub.ID, "HALF", t0); !errors.Is(err, ErrCouponApplied) {
		t.Fatalf("second coupon: %v", err)
	}

	if _, err := s.ApplyCoupon(a.ID, newSub(usd).ID, "ONCE", t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(a.ID, newSub(usd).ID, "ONCE", t0); !errors.Is(err, ErrCouponExhausted) {
		t.Fatalf("past max_redemptions: %v", err)
	}
	if n := s.CouponRedemptions(a.ID, "ONCE"); n != 1 {
		t.Fatalf("CouponRedemptions = %d", n)
	}

	canceled := newSub(usd)
	if _, err := s.UpdateSubscription(a.ID, canceled.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
