func TestApplyCoupon(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	usd, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	eur, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.EUR, UnitAmount: 2000, Interval: Monthly}, t0)
	newSub := func(plan Plan) Subscription {
		t.Helper()
		sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: plan.ID, Quantity: 1, Status: Active,
			StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: t0.AddDate(0, 1, 0)}, t0)
		if err != nil {
			t.Fatal(err)
		}
		return sub
	}
	create := func(c Coupon) {
		t.Helper()
		c.OrgID = a.ID
		if _, err := s.CreateCoupon(c, t0); err != nil {
			t.Fatal(err)
		}
	}
	create(Coupon{Code: "HALF", PercentOff: 50, Duration: CouponForever})
	create(Coupon{Code: "TENOFF", AmountOff: 1000, Currency: money.USD, Duration: CouponOnce})
	create(Coupon{Code: "EXPIRED", PercentOff: 5, Duration: CouponOnce, RedeemBy: &t0})
	create(Coupon{Code: "ONCE", PercentOff: 5, Duration: CouponOnce, MaxRedemptions: 1})

	sub := newSub(usd)
	if _, err := s.ApplyCoupon(a.ID, sub.ID, "NOPE", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown code: %v", err)
	}
	if _, err := s.ApplyCoupon(b.ID, sub.ID, "HALF", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription of another organization: %v", err)
	}
	if _, err := s.ApplyCoupon(a.ID, newSub(eur).ID, "TENOFF", t0); !errors.Is(err, ErrCurrencyMismatch) {
		t.Fatalf("amount in another currency: %v", err)
	}
	if _, err := s.ApplyCoupon(a.ID, sub.ID, "EXPIRED", t0.Add(time.Second)); !errors.Is(err, ErrCouponExpired) {
		t.Fatalf("after redeem_by: %v", err)
	}

	applied, err := s.ApplyCoupon(a.ID, sub.ID, "tenoff", t0.Add(time.Hour))
	if err != nil || applied.Coupon != "TENOFF" || applied.CouponRedeemedAt == nil || !applied.CouponRedeemedAt.Equal(t0.Add(time.Hour)) {
		t.Fatalf("ApplyCoupon = %+v, %v", applied, err)
	}
	if _, err := s.ApplyCoupon(a.ID, sub.ID, "HALF", t0); !errors.Is(err, ErrCouponApplied) {
		t.Fatalf("second coupon: %v", err)
	}

	if _, err := s.ApplyCoupon(a.ID, newSub(usd).ID, "ONCE", t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(a.ID, newSub(usd).ID, "ONCE", t0); !errors.Is(err, ErrCouponExhausted) {
		t.Fatalf("past max_redemptions: %v", err)
	}
	if n := s.CouponRedemptions(a.ID, "ONCE"); n != 1 {
		t.Fatalf("CouponRedemptions = %d", n)
	}

	canceled := newSub(usd)
	if _, err := s.UpdateSubscription(a.ID, canceled.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(a.ID, canceled.ID, "HALF", t0); !errors.Is(err, ErrSubscriptionCanceled) {
		t.Fatalf("canceled subscription: %v", err)
	}
}

