		t.Fatalf("CouponRedemptions = %d", n)
	}

	canceled := newSub(usd)
	if _, err := s.UpdateSubscription(a.ID, canceled.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	if _, err := s.ApplyCoupon(a.ID, canceled.ID, "HALF", t0); !errors.Is(err, ErrSubscriptionCanceled) {
		t.Fatalf("canceled subscription: %v", err)
	}
}

