		t.Fatalf("the same code in another organization: %s", r)
	}

	invalid := []map[string]any{
		{"code": "AB", "percent_off": 10, "duration": "once"},
		{"code": "BAD CODE", "percent_off": 10, "duration": "once"},
		{"code": "BOTH1", "percent_off": 10, "amount_off": "5", "currency": "USD", "duration": "once"},
		{"code": "NEITHER1", "duration": "once"},
		{"code": "PCT101", "percent_off": 101, "duration": "once"},
		{"code": "AMT0", "amount_off": "0", "currency": "USD", "duration": "once"},
		{"code": "AMTX", "amount_off": "12.5x", "currency": "USD", "duration": "once"},
		{"code": "NOCUR", "amount_off": "5", "duration": "once"},
		{"code": "PCTCUR", "percent_off": 10, "currency": "USD", "duration": "once"},
		{"code": "REP1", "percent_off": 10, "duration": "repeating"},
		{"code": "REP37", "percent_off": 10, "duration": "repeating", "duration_in_months": 37},
		{"code": "ONCEM", "percent_off": 10, "duration": "once", "duration_in_months": 3},
		{"code": "MAX0", "percent_off": 10, "duration": "forever", "max_redemptions": 0},
		{"code": "WHEN1", "percent_off": 10, "duration": "once", "redeem_by": "next tuesday"},
		{"code": "DUR1", "percent_off": 10, "duration": "weekly"},
	}
	for _, body := range invalid {
		if r := e.Do("POST", "/v1/coupons", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid" {
			t.Errorf("%v: %s", body, r)
		}
	}

	var limited coupon
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "TWOMO", "percent_off": 25, "duration": "repeating",
		"duration_in_months": 2, "max_redemptions": 1, "redeem_by": "2027-01-01T00:00:00Z"}, &limited)
	if limited.DurationInMonths != 2 || limited.MaxRedemptions != 1 || limited.RedeemBy == nil {
		t.Fatalf("repeating coupon = %+v", limited)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "EXPIRED", "percent_off": 5, "duration": "once",
		"redeem_by": "2026-01-01T00:00:00Z"}, nil)

	var list struct{ Items []coupon }
	e.MustDo(http.StatusOK, "GET", "/v1/coupons", e.Acme.Key, nil, &list)
	if len(list.Items) != 4 || list.Items[0].Code != "SPRING10" || list.Items[1].Code != "TENOFF" {
		t.Fatalf("list = %+v, want the organization's coupons oldest first", list.Items)
	}
	var got coupon
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/tenoff", e.Acme.Key, nil, &got)
	if got.ID != amt.ID {
		t.Fatalf("GET ignoring case = %+v", got)
	}
	if r := e.Do("GET", "/v1/coupons/NOPE", e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("missing coupon: %s", r)
	}

	usd := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	eur := e.CreatePlan(e.Acme, "Team EUR", "EUR", "20.00")
	customer := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	subscribe := func(planID string) store.Subscription {
		t.Helper()
		var sub store.Subscription
		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": customer.ID, "plan_id": planID}, &sub)
		return sub
	}
	apply := func(sub store.Subscription, code string) *apitest.Response {
		t.Helper()
		return e.Do("POST", "/v1/subscriptions/"+sub.ID+"/coupon", e.Acme.Key, map[string]string{"code": code})
	}
	first, second, third := subscribe(usd.ID), subscribe(usd.ID), subscribe(usd.ID)
	inEUR := subscribe(eur.ID)
	canceled := subscribe(usd.ID)

	if r := apply(first, "NOPE"); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("unknown coupon: %s", r)
	}
	if r := apply(first, "TENOFF"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "currency_mismatch" {
		t.Fatalf("EUR coupon on a USD plan: %s", r)
	}
	if r := apply(first, "EXPIRED"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_expired" {
		t.Fatalf("expired coupon: %s", r)
	}
	var applied store.Subscription
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+first.ID+"/coupon", e.Acme.Key, map[string]string{"code": "spring10"}, &applied)
	if applied.Coupon != "SPRING10" || applied.CouponRedeemedAt == nil {
		t.Fatalf("applied = %+v", applied)
	}
	if r := apply(first, "TWOMO"); r.Code != http.StatusConflict || r.Map(t)["error"] != "coupon_already_applied" {
		t.Fatalf("second coupon: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+inEUR.ID+"/coupon", e.Acme.Key, map[string]string{"code": "TENOFF"}, &inEUR)
	if inEUR.Coupon != "TENOFF" {
		t.Fatalf("EUR subscription = %+v", inEUR)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+second.ID+"/coupon", e.Acme.Key, map[string]string{"code": "TWOMO"}, nil)
	if r := apply(third, "TWOMO"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_exhausted" {
		t.Fatalf("exhausted coupon: %s", r)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+canceled.ID+"/cancel", e.Acme.Key, nil, nil)
	if r := apply(canceled, "SPRING10"); r.Code != http.StatusConflict || r.Map(t)["error"] != "subscription_canceled" {
		t.Fatalf("canceled subscription: %s", r)
	}

	e.MustDo(http.StatusOK, "GET", "/v1/coupons/TWOMO", e.Acme.Key, nil, &got)
	if got.TimesRedeemed != 1 {
		t.Fatalf("times_redeemed = %d", got.TimesRedeemed)
	}

	// The first renewal is invoiced with the coupon; the subscription's own 10 percent discount is not used on it.
	e.Clock.Set(applied.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(e.Clock.Context()); err != nil {
		t.Fatal(err)
	}
	var invs struct {
		Items []struct {
			Coupon   string `json:"coupon"`
			Discount int64  `json:"discount"`
			Total    int64  `json:"total"`
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?subscription_id="+first.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 2 || invs.Items[0].Coupon != "" || invs.Items[1].Coupon != "SPRING10" || invs.Items[1].Discount != 200 || invs.Items[1].Total != 1800 {
		t.Fatalf("invoices = %+v", invs.Items)
	}
}

